  SELECT id INTO qid FROM question WHERE content_key = 'gate-2008-23';
  IF qid IS NULL THEN
    SELECT qs.question_id INTO qid FROM question_source qs JOIN source s ON s.id = qs.source_id
      JOIN question x ON x.id = qs.question_id
      WHERE (s.code, qs.q_no) IN (('GATE-2008', '23')) AND x.content_key IS NULL
      ORDER BY qs.question_id LIMIT 1;
  END IF;
  IF qid IS NULL THEN
    INSERT INTO question(subject_id, topic_id, nature, summary, stem_md, solution_md, status, answer_type, nat_min, nat_max,
                         difficulty, answer_status, content_key, origin)
    VALUES (subj, tid, 'NUMERICAL', 'Assuming ideal elements in the circuit shown below, the voltage $v{ab}$ will be', 'Assuming ideal elements in the circuit shown below, the voltage $v_{ab}$ will be

![Figure](fig:q-gate2008-23)
', '**Idea used:** the current source fixes the loop current; then walk from a to b with KVL (see *KCL and KVL: a first look*).

1. Single loop ⇒ loop current $= 1$ A (set by the current source). It flows up through the current source (from b to a), right through the 2 Ω resistor, down through the 5 V source, and back along the bottom to b.
2. Walk from **a** to **b** along the right-hand path:
   - Through the 2 Ω resistor in the direction of the current: a drop of $1\times2 = 2$ V. So $v_a - v_{\text{right top}} = 2$ V.
   - Through the 5 V source from its top (–) to its bottom (+): the bottom is 5 V higher, so $v_{\text{right top}} - v_b = -5$ V.
3. Add: $v_{ab} = v_a - v_b = 2 + (-5) = -3$ V.

**Without a calculator:** $2 - 5 = -3$ V.

**Answer: (A) −3 V.**
', 'READY', 'MCQ', NULL, NULL, 1, 'UNVERIFIED', 'gate-2008-23', 'PYQ') RETURNING id INTO qid;
