', status = 'READY', answer_type = 'MCQ', nat_min = NULL, nat_max = NULL, difficulty = 1, answer_status = 'UNVERIFIED', content_key = 'gate-2008-23', origin = 'PYQ', updated_at = now() WHERE id = qid;
