DECLARE qid int; subj int; tid int;
BEGIN
  SELECT id INTO subj FROM subject WHERE slug = 'electric-circuits';
  SELECT id INTO tid FROM topic WHERE subject_id = subj AND slug = 'ec1-kcl-kvl-first-look';
  SELECT id INTO qid FROM question WHERE content_key = 'gate-2017-s1-18';
  IF qid IS NULL THEN
    SELECT qs.question_id INTO qid FROM question_source qs JOIN source s ON s.id = qs.source_id
      JOIN question x ON x.id = qs.question_id
      WHERE (s.code, qs.q_no) IN (('GATE-2017_1', '18')) AND x.content_key IS NULL
      ORDER BY qs.question_id LIMIT 1;
  END IF;
  IF qid IS NULL THEN
    INSERT INTO question(subject_id, topic_id, nature, summary, stem_md, solution_md, status, answer_type, nat_min, nat_max,
                         difficulty, answer_status, content_key, origin)
    VALUES (subj, tid, 'NUMERICAL', 'The power supplied by the 25 V source in the figure shown below is W.', 'The power supplied by the 25 V source in the figure shown below is ______ W.

![Figure](fig:q-gate2017s1-18)
', '**Idea used:** KCL at one node with a dependent source, then $p = vi$ for the source (see *KCL and KVL → Example 3* and *Dependent sources*).

1. The current $I$ leaves the + terminal of the 25 V source and flows through $R_1$ to the right-hand node.
2. At that node: $I$ comes in through $R_1$, the dependent source pushes $0.4I$ **up** into the node, and 14 A goes **down** through $R_2$.
3. KCL: $I + 0.4I = 14$ ⇒ $1.4I = 14$ ⇒ $I = 10$ A.
4. The 25 V source carries 10 A out of its + terminal, so it supplies $P = 25\times10 = 250$ W.

Extra check: KVL gives the voltage of the right node $= 25 - 17 = 8$ V, which is the voltage across $R_2$ (shown with + at the top) ✔. You do not need $R_1$ or $R_2$ themselves.

**Without a calculator:** $14 \div 1.4 = 140 \div 14 = 10$ A, then $25 \times 10 = 250$ W.

**Answer: 250 W.**
', 'READY', 'NAT', 250, 250, 2, 'UNVERIFIED', 'gate-2017-s1-18', 'PYQ') RETURNING id INTO qid;
  ELSE
    UPDATE question SET subject_id = subj, topic_id = tid, nature = 'NUMERICAL', summary = COALESCE(NULLIF(summary, ''), 'The power supplied by the 25 V source in the figure shown below is W.'), stem_md = 'The power supplied by the 25 V source in the figure shown below is ______ W.

![Figure](fig:q-gate2017s1-18)
