DECLARE qid int; subj int; tid int;
BEGIN
  SELECT id INTO subj FROM subject WHERE slug = 'electric-circuits';
  SELECT id INTO tid FROM topic WHERE subject_id = subj AND slug = 'ec1-kcl-kvl-first-look';
  SELECT id INTO qid FROM question WHERE content_key = 'gate-2003-segment';
  IF qid IS NULL THEN
    SELECT qs.question_id INTO qid FROM question_source qs JOIN source s ON s.id = qs.source_id
      JOIN question x ON x.id = qs.question_id
      WHERE (s.code, qs.q_no) IN (('GATE-2003', '~segment-vl')) AND x.content_key IS NULL
      ORDER BY qs.question_id LIMIT 1;
  END IF;
  IF qid IS NULL THEN
    INSERT INTO question(subject_id, topic_id, nature, summary, stem_md, solution_md, status, answer_type, nat_min, nat_max,
                         difficulty, answer_status, content_key, origin)
    VALUES (subj, tid, 'NUMERICAL', 'A segment of a circuit is shown in figure. $vR = 5\ \text{V}$, $vC = 4\sin2t$. The voltage $vL$ is given by', 'A segment of a circuit is shown in figure. $v_R = 5\ \text{V}$, $v_C = 4\sin2t$. The voltage $v_L$ is given by

![Figure](fig:q-gate2003-segment)
', '**Idea used:** element laws for each branch, then KCL at the centre node (see *KCL and KVL → Example 5*).

All four branches meet at the centre node N.

1. **Current source:** 2 A from P **into** N.
2. **5 Ω resistor:** $v_R = 5$ V with + at Q, so current flows from Q **into** N: $5/5 = 1$ A.
3. **1 F capacitor:** $v_C$ has + at N, so the current from N through the capacitor towards R is $i_C = C\,\dfrac{dv_C}{dt} = 1\times8\cos2t = 8\cos2t$ A, **out of** N.
4. **2 H inductor:** current $i_L$ from N down to S, **out of** N.
5. KCL at N: $2 + 1 = 8\cos2t + i_L$ ⇒ $i_L = 3 - 8\cos2t$ A.
6. $v_L$ (+ at N) $= L\,\dfrac{di_L}{dt} = 2\times(16\sin2t) = 32\sin2t$ V.

Trap: option (A) is $i_L$, the inductor **current**, not its voltage.

**Without a calculator:** Only derivatives of $\sin 2t$ and $\cos 2t$: each derivative brings a factor 2. $4 \times 2 = 8$, then $8 \times 2 \times 2 = 32$.

**Answer: (B) $32\sin2t$.**
', 'READY', 'MCQ', NULL, NULL, 2, 'TWO_SOURCES', 'gate-2003-segment', 'PYQ') RETURNING id INTO qid;
  ELSE
    UPDATE question SET subject_id = subj, topic_id = tid, nature = 'NUMERICAL', summary = COALESCE(NULLIF(summary, ''), 'A segment of a circuit is shown in figure. $vR = 5\ \text{V}$, $vC = 4\sin2t$. The voltage $vL$ is given by'), stem_md = 'A segment of a circuit is shown in figure. $v_R = 5\ \text{V}$, $v_C = 4\sin2t$. The voltage $v_L$ is given by

