END $ppimport$;
DO $ppimport$
DECLARE qid int; subj int; tid int;
BEGIN
  SELECT id INTO subj FROM subject WHERE slug = 'electric-circuits';
  SELECT id INTO tid FROM topic WHERE subject_id = subj AND slug = 'ec1-kcl-kvl-first-look';
  SELECT id INTO qid FROM question WHERE content_key = 'gate-2014-s1-8';
  IF qid IS NULL THEN
    SELECT qs.question_id INTO qid FROM question_source qs JOIN source s ON s.id = qs.source_id
      JOIN question x ON x.id = qs.question_id
      WHERE (s.code, qs.q_no) IN (('GATE-2014', 'S1-Q8')) AND x.content_key IS NULL
      ORDER BY qs.question_id LIMIT 1;
  END IF;
  IF qid IS NULL THEN
    INSERT INTO question(subject_id, topic_id, nature, summary, stem_md, solution_md, status, answer_type, nat_min, nat_max,
                         difficulty, answer_status, content_key, origin)
    VALUES (subj, tid, 'NUMERICAL', 'A combination of 1 µF capacitor with an initial voltage $vc(0) = -2$ V in series with a 100 Ω resistor is connected to a 20 mA ideal dc current source by...', 'A combination of 1 µF capacitor with an initial voltage $v_c(0) = -2$ V in series with a 100 Ω resistor is connected to a 20 mA ideal dc current source by operating both switches at t = 0 s as shown. Which of the following graphs shown in the options approximates the voltage $v_s$ across the current source over the next few seconds?

![Figure](fig:q-gate2014-s1-8)
', '**Idea used:** a capacitor fed by an ideal current source charges linearly, $v = v(0) + \dfrac{I}{C}t$; the voltage across a current source comes from KVL (see *The capacitor → Two useful circuit cases* and *KCL and KVL*).

After $t = 0$ the current source, the capacitor and the 100 Ω resistor form one loop carrying exactly 20 mA, going in at the + side of $v_c$.

1. Resistor voltage: $0.02\times100 = 2$ V, constant.
2. Capacitor voltage: $v_c(t) = -2 + \dfrac{0.02}{1\times10^{-6}}\,t = -2 + 20\,000\,t$ V.
3. KVL: $v_s = v_c + v_R = (-2 + 20\,000\,t) + 2 = 20\,000\,t$ V.

So $v_s$ **starts at 0** at $t = 0^+$ and rises in a **straight line**. (A real exponential would need a resistor in parallel; with an ideal current source the charging is linear.) Options (B) and (D) are exponential; option (A) starts at –2 V (it forgets the resistor''s 2 V).

**Without a calculator:** $0.02 \div 10^{-6} = 20\,000$ V/s. The resistor''s $+2$ V cancels the capacitor''s $-2$ V, so the graph starts at 0.

**Answer: (C).**
', 'READY', 'MCQ', NULL, NULL, 2, 'UNVERIFIED', 'gate-2014-s1-8', 'PYQ') RETURNING id INTO qid;
  ELSE
    UPDATE question SET subject_id = subj, topic_id = tid, nature = 'NUMERICAL', summary = COALESCE(NULLIF(summary, ''), 'A combination of 1 µF capacitor with an initial voltage $vc(0) = -2$ V in series with a 100 Ω resistor is connected to a 20 mA ideal dc current source by...'), stem_md = 'A combination of 1 µF capacitor with an initial voltage $v_c(0) = -2$ V in series with a 100 Ω resistor is connected to a 20 mA ideal dc current source by operating both switches at t = 0 s as shown. Which of the following graphs shown in the options approximates the voltage $v_s$ across the current source over the next few seconds?

![Figure](fig:q-gate2014-s1-8)
', solution_md = '**Idea used:** a capacitor fed by an ideal current source charges linearly, $v = v(0) + \dfrac{I}{C}t$; the voltage across a current source comes from KVL (see *The capacitor → Two useful circuit cases* and *KCL and KVL*).

