DO $ppimport$
DECLARE qid int; subj int; tid int;
BEGIN
  SELECT id INTO subj FROM subject WHERE slug = 'electric-circuits';
  SELECT id INTO tid FROM topic WHERE subject_id = subj AND slug = 'ec1-kcl-kvl-first-look';
  SELECT id INTO qid FROM question WHERE content_key = 'ese-2026-101';
  IF qid IS NULL THEN
    SELECT qs.question_id INTO qid FROM question_source qs JOIN source s ON s.id = qs.source_id
      JOIN question x ON x.id = qs.question_id
      WHERE (s.code, qs.q_no) IN (('ESE-2026', '101')) AND x.content_key IS NULL
      ORDER BY qs.question_id LIMIT 1;
  END IF;
  IF qid IS NULL THEN
    INSERT INTO question(subject_id, topic_id, nature, summary, stem_md, solution_md, status, answer_type, nat_min, nat_max,
                         difficulty, answer_status, content_key, origin)
    VALUES (subj, tid, 'NUMERICAL', 'What is the power supplied by each element in the circuit shown below?', 'What is the power supplied by each element in the circuit shown below?

![Figure](fig:q-ese2026-101)
', '**Idea used:** passive sign convention for each element, and power balance as a check (see *Power and energy*).

Read the circuit: $I = 5$ A leaves the + terminal of the 20 V source ($P_1$) and flows through element $P_2$ (12 V, + on the left), then 6 A flows down through element $P_3$ (8 V, + at the top). The dependent source $P_4$ carries $0.2I = 1$ A **upward** and has the same 8 V across it (+ at the top). KCL check: $5 + 1 = 6$ ✔. KVL check: $20 = 12 + 8$ ✔.

**Absorbed power of each element:**
- $P_1$: 5 A leaves its + terminal ⇒ $-20\times5 = -100$ W
- $P_2$: 5 A enters its + terminal ⇒ $+12\times5 = +60$ W
- $P_3$: 6 A enters its + terminal ⇒ $+8\times6 = +48$ W
- $P_4$: 1 A leaves its + terminal (it flows up) ⇒ $-8\times1 = -8$ W
- Sum $= -100 + 60 + 48 - 8 = 0$ ✔ (power balance)

**Supplied power** is the same with the opposite sign: $P_1 = +100$, $P_2 = -60$, $P_3 = -48$, $P_4 = +8$ W.

**Defect in this question:** the circuit and the numbers come from Sadiku''s textbook (Example 1.7), which lists *absorbed* powers: that set is option (D). But the question asks for the power **supplied**, and that set is exactly option (B). Both options are marked correct here until the UPSC key is checked. In the exam, the words "power supplied" point to (B); the setter''s source points to (D).

**Without a calculator:** Only small products: $20\times5$, $12\times5$, $8\times6$, $8\times1$. Use the power balance $-100 + 60 + 48 - 8 = 0$ as your check.

**Answer: (B) by the wording (supplied power); (D) if the setter meant absorbed power.**
', 'READY', 'MCQ', NULL, NULL, 2, 'UNVERIFIED', 'ese-2026-101', 'PYQ') RETURNING id INTO qid;
  ELSE
    UPDATE question SET subject_id = subj, topic_id = tid, nature = 'NUMERICAL', summary = COALESCE(NULLIF(summary, ''), 'What is the power supplied by each element in the circuit shown below?'), stem_md = 'What is the power supplied by each element in the circuit shown below?

![Figure](fig:q-ese2026-101)
', solution_md = '**Idea used:** passive sign convention for each element, and power balance as a check (see *Power and energy*).

Read the circuit: $I = 5$ A leaves the + terminal of the 20 V source ($P_1$) and flows through element $P_2$ (12 V, + on the left), then 6 A flows down through element $P_3$ (8 V, + at the top). The dependent source $P_4$ carries $0.2I = 1$ A **upward** and has the same 8 V across it (+ at the top). KCL check: $5 + 1 = 6$ ✔. KVL check: $20 = 12 + 8$ ✔.

**Absorbed power of each element:**
- $P_1$: 5 A leaves its + terminal ⇒ $-20\times5 = -100$ W
- $P_2$: 5 A enters its + terminal ⇒ $+12\times5 = +60$ W
- $P_3$: 6 A enters its + terminal ⇒ $+8\times6 = +48$ W
- $P_4$: 1 A leaves its + terminal (it flows up) ⇒ $-8\times1 = -8$ W
- Sum $= -100 + 60 + 48 - 8 = 0$ ✔ (power balance)

**Supplied power** is the same with the opposite sign: $P_1 = +100$, $P_2 = -60$, $P_3 = -48$, $P_4 = +8$ W.

**Defect in this question:** the circuit and the numbers come from Sadiku''s textbook (Example 1.7), which lists *absorbed* powers: that set is option (D). But the question asks for the power **supplied**, and that set is exactly option (B). Both options are marked correct here until the UPSC key is checked. In the exam, the words "power supplied" point to (B); the setter''s source points to (D).

**Without a calculator:** Only small products: $20\times5$, $12\times5$, $8\times6$, $8\times1$. Use the power balance $-100 + 60 + 48 - 8 = 0$ as your check.

**Answer: (B) by the wording (supplied power); (D) if the setter meant absorbed power.**
', status = 'READY', answer_type = 'MCQ', nat_min = NULL, nat_max = NULL, difficulty = 2, answer_status = 'UNVERIFIED', content_key = 'ese-2026-101', origin = 'PYQ', updated_at = now() WHERE id = qid;
  END IF;
